import java.util.HashMap;
import java.util.Map;

public class Solution {
    static class LRU {
        private static class Node {
            int key, value;
            Node prev, next;
            Node(int key, int value) { this.key = key; this.value = value; }
        }

        private final int capacidade;
        private final Map<Integer, Node> mapa = new HashMap<>();
        private final Node head = new Node(0, 0), tail = new Node(0, 0);
        private int evictions;

        LRU(int capacidade) {
            this.capacidade = capacidade;
            head.next = tail;
            tail.prev = head;
        }

        private void unlink(Node n) {
            n.prev.next = n.next;
            n.next.prev = n.prev;
        }

        private void pushFront(Node n) {
            n.prev = head;
            n.next = head.next;
            head.next.prev = n;
            head.next = n;
        }

        // O(1): o mapa acha o nó; a lista o move para a frente.
        int get(int key) {
            Node n = mapa.get(key);
            if (n == null) return -1;
            unlink(n);
            pushFront(n);
            return n.value;
        }

        void put(int key, int value) {
            Node n = mapa.get(key);
            if (n != null) {
                n.value = value;
                unlink(n);
                pushFront(n);
                return;
            }
            if (mapa.size() == capacidade) {
                Node velho = tail.prev; // menos recente
                unlink(velho);
                mapa.remove(velho.key); // por isso o nó guarda a chave
                evictions++;
            }
            n = new Node(key, value);
            pushFront(n);
            mapa.put(key, n);
        }

        int size() { return mapa.size(); }
        int evictions() { return evictions; }
    }
}

