import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void evictaMenosRecente() {
        var c = new Solution.LRU(2);
        c.put(1, 1); c.put(2, 2);
        assertEquals(1, c.get(1));   // 1 vira o mais recente
        c.put(3, 3);                 // evicta 2
        assertEquals(-1, c.get(2));
        assertEquals(1, c.get(1));
        assertEquals(3, c.get(3));
        assertEquals(1, c.evictions());
    }

    @Test void atualizarNaoEvictaETornaRecente() {
        var c = new Solution.LRU(2);
        c.put(1, 1); c.put(2, 2);
        c.put(1, 10);                // atualiza, 1 vira recente
        assertEquals(0, c.evictions());
        c.put(3, 3);                 // evicta 2
        assertEquals(10, c.get(1));
        assertEquals(-1, c.get(2));
        assertEquals(2, c.size());
    }

    @Test void capacidadeUm() {
        var c = new Solution.LRU(1);
        c.put(1, 1); c.put(2, 2);
        assertEquals(-1, c.get(1));
        assertEquals(2, c.get(2));
    }

    @Test void muitasOperacoes() {
        var c = new Solution.LRU(1000);
        for (int i = 0; i < 300_000; i++) {
            c.put(i, i);
            if (i >= 10) c.get(i - 10);
        }
        assertEquals(1000, c.size());
        assertEquals(299_000, c.evictions());
        assertEquals(299_990, c.get(299_990));
    }
}
